<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        #claim-form, #confirmation { max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ccc; border-radius: 5px; }
        #confirmation { display: none; }
        .step { margin-bottom: 20px; }
        footer { text-align: center; margin-top: 40px; font-size: 0.9em; color: #555; }
        .file-names { margin-top: 10px; }
    </style>
</head>
<body>
    <div id="how-it-works">
        <h2>How it works</h2>
        <div class="step"><strong>Step 1:</strong> Enter the policy number and member ID, then click 'Look up member'.</div>
        <div class="step"><strong>Step 2:</strong> Fill in the claim details including dates and nature of absence.</div>
        <div class="step"><strong>Step 3:</strong> Upload relevant documents and submit the form to start the claim process.</div>
    </div>

    <form id="claim-form">
        <h2>Disability Claim Submission</h2>
        <div>
            <label for="policy-number">Policy Number:</label>
            <input type="text" id="policy-number" required />
        </div>
        <div>
            <label for="member-id">Member ID:</label>
            <input type="text" id="member-id" required />
            <button type="button" onclick="lookupMember()">Look up member</button>
        </div>
        <div id="member-details"></div>
        <div>
            <label for="last-day-worked">Last Day Worked:</label>
            <input type="date" id="last-day-worked" required />
        </div>
        <div>
            <label for="first-day-absent">First Day Absent:</label>
            <input type="date" id="first-day-absent" required />
        </div>
        <div>
            <label for="nature-of-absence">Nature of Absence:</label>
            <select id="nature-of-absence" required>
                <option value="">Select</option>
                <option value="sickness">Sickness</option>
                <option value="injury">Injury</option>
                <option value="other">Other</option>
            </select>
        </div>
        <div>
            <label for="details">Details:</label>
            <textarea id="details" rows="4"></textarea>
        </div>
        <div>
            <label for="documents">Upload Documents:</label>
            <input type="file" id="documents" multiple />
            <div class="file-names" id="file-names"></div>
        </div>
        <button type="submit">Submit Claim</button>
    </form>

    <div id="confirmation">
        <h2>Submission Received</h2>
        <p>Your claim reference number is <span id="reference-number"></span>.</p>
        <p>Status: Received</p>
    </div>

    <footer>MapleSure Insurance — fictional demo application</footer>

    <script>
        const members = {
            "1234": "Member: John Doe",
            "5678": "Member: Jane Smith"
        };

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = members[memberId] || "Member not found";
            document.getElementById('member-details').innerText = memberDetails;
        }

        document.getElementById('documents').addEventListener('change', function(event) {
            const files = event.target.files;
            const fileNames = Array.from(files).map(file => file.name).join(', ');
            document.getElementById('file-names').innerText = fileNames;
        });

        document.getElementById('claim-form').addEventListener('submit', function(event) {
            event.preventDefault();
            const referenceNumber = 'MS-2026-08-' + Math.floor(Math.random() * 10000).toString().padStart(4, '0');
            document.getElementById('reference-number').innerText = referenceNumber;
            document.getElementById('claim-form').style.display = 'none';
            document.getElementById('confirmation').style.display = 'block';
        });
    </script>
</body>
</html>
"}]}
